export function localizeEvidence(label: string, lang: Language): string {
  if (!label || lang === "tr") return label;
  return evidenceLabelsDict[label]?.[lang] ?? label;
}

export function localizeAttribute(label: string, lang: Language): string {
  if (!label || lang === "tr") return label;
  return attributeLabelsDict[label]?.[lang] ?? label;
}

export function localizeNotice(notice: string, lang: Language): string {
  if (!notice || lang === "tr") return notice;
  
  if (noticeDict[notice]?.[lang]) {
    return noticeDict[notice][lang];
  }

  // Refill scan pattern: "X yenileme hakkın geri doldu."
  let match = notice.match(/^(\d+) yenileme hakkın geri doldu\.$/);
  if (match) {
    if (lang === "de") return `${match[1]} Scan-Credits wieder aufgeladen.`;
    if (lang === "es") return `${match[1]} créditos de exploración recargados.`;
    return `${match[1]} scan credits restored.`;
  }

  // Cash shortfall pattern: "X nakit eksik. Önce satış yap."
  match = notice.match(/^(.*) nakit eksik\. Önce satış yap\.$/);
  if (match) {
    if (lang === "de") return `${match[1]} fehlen. Zuerst verkaufen.`;
    if (lang === "es") return `Faltan ${match[1]}. Vende primero.`;
    return `Need ${match[1]} more cash. Sell first.`;
  }

  // Welcome pattern: "Hoş geldin, NAME. İlk fırsatın hazır."
  match = notice.match(/^Hoş geldin, (.*)\. İlk fırsatın hazır\.$/);
  if (match) {
    if (lang === "de") return `Willkommen, ${match[1]}. Dein erster Deal ist bereit.`;
    if (lang === "es") return `Bienvenido, ${match[1]}. Tu primera oportunidad está lista.`;
    return `Welcome, ${match[1]}. Your first deal is ready.`;
  }

  // Sound level pattern: "Ses seviyesi X olarak ayarlandı."
  match = notice.match(/^Ses seviyesi (.*) olarak ayarlandı\.$/);
  if (match) {
    const sound = match[1] === "kapalı" ? (lang === "de" ? "Stumm" : lang === "es" ? "Silencio" : "Off")
      : match[1] === "düşük" ? (lang === "de" ? "Leise" : lang === "es" ? "Bajo" : "Low")
      : (lang === "de" ? "Normal" : lang === "es" ? "Normal" : "Normal");
    if (lang === "de") return `Lautstärke auf ${sound} eingestellt.`;
    if (lang === "es") return `Sonido configurado en ${sound}.`;
    return `Sound level set to ${sound}.`;
  }

  // Synced purchases: "X mağaza hakkı doğrulandı."
  match = notice.match(/^(\d+) mağaza hakkı doğrulandı\.$/);
  if (match) {
    if (lang === "de") return `${match[1]} Store-Berechtigungen bestätigt.`;
    if (lang === "es") return `${match[1]} compras de la tienda confirmadas.`;
    return `${match[1]} store entitlements verified.`;
  }

  return notice;
}
